package cn.cnxice.cobblemonfix.mixin;
import com.cobblemon.mod.common.api.abilities.*; import com.cobblemon.mod.common.api.Priority; import com.cobblemon.mod.common.util.adapters.AbilityPoolAdapter; import com.google.gson.JsonElement; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable; import java.lang.reflect.Type;
@Mixin(value=AbilityPoolAdapter.class, remap=false) public abstract class CobblemonAbilityPoolMixin { @Inject(method="deserialize", at=@At("HEAD"), cancellable=true, remap=false) private void xice(JsonElement j, Type t, com.google.gson.JsonDeserializationContext c, CallbackInfoReturnable<AbilityPool> cir) { if(!j.isJsonArray()) return; for(JsonElement e:j.getAsJsonArray()) if(e.isJsonPrimitive()&&"xice_dark_shroud".equals(e.getAsString())) { AbilityTemplate a=new AbilityTemplate("xice_dark_shroud",(x,f,p)->new Ability(x,f,p),"cobblemon.ability.xice_dark_shroud","cobblemon.ability.xice_dark_shroud.desc"); AbilityPool p=new AbilityPool(); p.add(Priority.NORMAL,new CommonAbility(a)); cir.setReturnValue(p); return; } } }
